insert into public.education_modules (id, key, title, level, level_name, description, position, status) values ('e3901149-4b43-56e1-821f-bc9ca15a68bf', 'poupanca', 'Poupança e hábito de guardar', 1, 'Iniciante', 'Poupar x investir, começar com pouco e montar sua reserva de emergência.', 1, 'publicado') on conflict (key) do update set title = excluded.title, level = excluded.level, level_name = excluded.level_name, description = excluded.description, position = excluded.position;
insert into public.education_lessons (id, module_id, key, title, position, status) values ('e3ab37b6-199a-53a7-8125-60fe1916aadf', 'e3901149-4b43-56e1-821f-bc9ca15a68bf', 'o-que-e', 'Poupar, investir e caderneta', 1, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('e3ab37b6-199a-53a7-8125-60fe1916aadf', 'Diferenciar poupar, investir e a caderneta de poupança.', 'Poupar é separar parte do dinheiro de hoje para o futuro. Investir é aplicar esse dinheiro em produtos financeiros buscando retorno, aceitando algum nível de risco. A caderneta de poupança é apenas um desses produtos: não é sinônimo de poupar.', 'Bia recebe R$ 200 de mesada e separa R$ 30 todo mês. Ela já está poupando, mesmo antes de escolher onde deixar esse dinheiro.', array['Poupar é um hábito; investir é uma escolha de aplicação.', 'A caderneta é um produto, não sinônimo de poupar.', 'Todo produto tem risco, liquidez e rendimento próprios.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}, {"n": "Portal do Investidor (CVM)", "u": "https://www.investidor.gov.br"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('afeeefce-155f-5362-a69b-b1bf90b43e9b', 'e3ab37b6-199a-53a7-8125-60fe1916aadf', 0, 'quiz', 'Qual afirmação está correta?', '{"opts": ["Poupar e investir são exatamente a mesma coisa", "Poupar é o hábito de separar dinheiro; investir é aplicá-lo em um produto financeiro", "Só quem tem caderneta de poupança está poupando", "Investir nunca envolve risco"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('afeeefce-155f-5362-a69b-b1bf90b43e9b', '1'::jsonb, 'Poupar é o hábito de separar dinheiro; investir é aplicá-lo em um produto financeiro', 'Poupar é o hábito; investir é a decisão de onde aplicar. A caderneta é só um dos produtos possíveis.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('e12bd45b-fff1-5b35-b689-9ee509b9e145', 'e3ab37b6-199a-53a7-8125-60fe1916aadf', 1, 'classify', 'Classifique cada situação:', '{"buckets": ["Hábito de poupar", "Produto financeiro"], "items": ["Separar R$ 30 da mesada todo mês", "Caderneta de poupança", "Guardar parte do pagamento de um trabalho eventual", "CDB"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('e12bd45b-fff1-5b35-b689-9ee509b9e145', '[0, 1, 0, 1]'::jsonb, 'Separar R$ 30 da mesada todo mês: Hábito de poupar; Caderneta de poupança: Produto financeiro; Guardar parte do pagamento de um trabalho eventual: Hábito de poupar; CDB: Produto financeiro', 'O hábito vem primeiro. Produtos financeiros são os lugares onde o dinheiro separado pode ficar.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_lessons (id, module_id, key, title, position, status) values ('eb7c1021-7199-51ac-a236-4bb82130a9cd', 'e3901149-4b43-56e1-821f-bc9ca15a68bf', 'vantagens', 'Reserva de emergência', 2, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('eb7c1021-7199-51ac-a236-4bb82130a9cd', 'Entender para que serve a reserva de emergência e quanto ela deve cobrir.', 'Reserva de emergência é dinheiro guardado para imprevistos, como um conserto urgente ou uma perda de renda. Ela precisa estar disponível rápido (liquidez) e com baixo risco de perda. Uma referência comum é cobrir alguns meses de gastos essenciais.', 'Se os gastos essenciais de Lucas são R$ 1.200 por mês e ele quer uma reserva de 3 meses, o alvo é R$ 3.600.', array['Reserva é para imprevistos, não para desejos.', 'Liquidez e segurança vêm antes de rentabilidade.', 'Uma referência: alguns meses de gastos essenciais.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('3b5c9fc9-2826-50af-9461-7f7110242cd3', 'eb7c1021-7199-51ac-a236-4bb82130a9cd', 0, 'multi', 'Quais situações justificam usar a reserva de emergência?', '{"opts": ["Conserto urgente do celular que você usa para estudar", "Promoção de um jogo novo", "Perda temporária de renda", "Ingresso de show"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('3b5c9fc9-2826-50af-9461-7f7110242cd3', '[0, 2]'::jsonb, 'Conserto urgente do celular que você usa para estudar; Perda temporária de renda', 'Reserva é para imprevistos e necessidades urgentes, não para desejos ou promoções.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('f89c0b4f-1244-56ac-b83f-ef8af9d543c3', 'eb7c1021-7199-51ac-a236-4bb82130a9cd', 1, 'calc', 'Gastos essenciais de R$ 1.200 por mês. Qual o valor de uma reserva de 3 meses?', '{"unit": "R$"}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('f89c0b4f-1244-56ac-b83f-ef8af9d543c3', '3600'::jsonb, 'R$ 3.600,00', '1.200 × 3 = 3.600. O número de meses é uma referência que você adapta à sua realidade.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('517af18e-13b9-50ff-bb77-cf6665a01781', 'eb7c1021-7199-51ac-a236-4bb82130a9cd', 2, 'quiz', 'Qual característica é mais importante numa reserva de emergência?', '{"opts": ["Rentabilidade máxima", "Liquidez: poder usar o dinheiro rápido", "Ficar preso por anos", "Risco alto"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('517af18e-13b9-50ff-bb77-cf6665a01781', '1'::jsonb, 'Liquidez: poder usar o dinheiro rápido', 'Num imprevisto, o dinheiro precisa estar disponível rapidamente.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_lessons (id, module_id, key, title, position, status) values ('fa3048b1-b929-5a46-92ec-a50d0d76cefc', 'e3901149-4b43-56e1-821f-bc9ca15a68bf', 'dicas', 'Começando com pouco', 3, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('fa3048b1-b929-5a46-92ec-a50d0d76cefc', 'Criar o hábito de guardar mesmo com valores pequenos.', 'Consistência vale mais do que valor. Separar um valor possível assim que o dinheiro entra, antes de gastar, é mais eficaz do que tentar guardar o que sobra.', 'Guardar R$ 25 por semana parece pouco, mas em 12 semanas soma R$ 300.', array['Pequenos valores constantes somam bastante.', 'Separe primeiro, gaste depois.', 'Revise o valor quando sua renda mudar.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('e069aa5e-80bf-5a56-96bf-69a35e4c1029', 'fa3048b1-b929-5a46-92ec-a50d0d76cefc', 0, 'calc', 'R$ 25 por semana durante 12 semanas. Quanto você terá guardado?', '{"unit": "R$"}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('e069aa5e-80bf-5a56-96bf-69a35e4c1029', '300'::jsonb, 'R$ 300,00', '25 × 12 = 300.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('bcab4376-dce7-5d70-87b5-1277ac71ed39', 'fa3048b1-b929-5a46-92ec-a50d0d76cefc', 1, 'quiz', 'Qual estratégia ajuda mais a manter o hábito?', '{"opts": ["Guardar só o que sobrar no fim do mês", "Separar um valor possível assim que o dinheiro entra", "Esperar ter um valor alto para começar", "Guardar só em datas especiais"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('bcab4376-dce7-5d70-87b5-1277ac71ed39', '1'::jsonb, 'Separar um valor possível assim que o dinheiro entra', 'Separar primeiro reduz a chance de gastar tudo sem perceber e torna o hábito automático.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
