insert into public.education_lessons (id, module_id, key, title, position, status) values ('e40b0a29-a981-5d8a-a3fe-69a186ed86ee', '6cf190d3-e1fd-59b2-bbcf-eaa17326893f', 'organizacao', 'Receitas e despesas', 1, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('e40b0a29-a981-5d8a-a3fe-69a186ed86ee', 'Registrar e classificar receitas e despesas.', 'Receita é todo dinheiro que entra. Despesa é todo dinheiro que sai. Registrar as duas mostra o resultado do mês: receitas menos despesas. Gastos fixos se repetem com valor parecido; variáveis mudam de mês a mês.', 'Em setembro, Caio recebeu R$ 300 de mesada e vendeu bolos por R$ 120. Gastou R$ 260 com lanche e transporte. Resultado: 420 − 260 = R$ 160.', array['Receita entra, despesa sai.', 'Resultado do mês = receitas − despesas.', 'Fixos são previsíveis; variáveis mudam.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('52bbe383-ffc3-5e79-bc8d-b412d0efc8f2', 'e40b0a29-a981-5d8a-a3fe-69a186ed86ee', 0, 'classify', 'Classifique cada item:', '{"buckets": ["Receita", "Despesa"], "items": ["Mesada", "Passagem de ônibus", "Venda de bolo", "Lanche na escola", "Assinatura de streaming", "Dinheiro de presente"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('52bbe383-ffc3-5e79-bc8d-b412d0efc8f2', '[0, 1, 0, 1, 1, 0]'::jsonb, 'Mesada: Receita; Passagem de ônibus: Despesa; Venda de bolo: Receita; Lanche na escola: Despesa; Assinatura de streaming: Despesa; Dinheiro de presente: Receita', 'Entrou dinheiro: receita. Saiu dinheiro: despesa.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('59045f56-a9d7-5d95-b886-d44243867499', 'e40b0a29-a981-5d8a-a3fe-69a186ed86ee', 1, 'calc', 'Receitas de R$ 420 e despesas de R$ 260. Qual o resultado do mês?', '{"unit": "R$"}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('59045f56-a9d7-5d95-b886-d44243867499', '160'::jsonb, 'R$ 160,00', '420 − 260 = 160. Resultado positivo significa que sobrou dinheiro.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('ea62b563-8d22-5f0f-96e1-dc2cda778851', 'e40b0a29-a981-5d8a-a3fe-69a186ed86ee', 2, 'quiz', 'Um gasto fixo é aquele que...', '{"opts": ["Muda muito todo mês", "Se repete com valor parecido, como assinatura ou mensalidade", "Só acontece uma vez", "Sempre é um desejo"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('ea62b563-8d22-5f0f-96e1-dc2cda778851', '1'::jsonb, 'Se repete com valor parecido, como assinatura ou mensalidade', 'Gastos fixos são previsíveis. Os variáveis, como lazer e lanches, mudam.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_lessons (id, module_id, key, title, position, status) values ('b741a9eb-c48c-5e77-9f00-b41df5fa1cac', '6cf190d3-e1fd-59b2-bbcf-eaa17326893f', 'erros', 'Necessidades, desejos e impulso', 2, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('b741a9eb-c48c-5e77-9f00-b41df5fa1cac', 'Separar necessidades de desejos e reconhecer compras por impulso.', 'Necessidades são gastos essenciais, como alimentação, transporte para estudar e material escolar. Desejos trazem prazer, mas podem esperar. Compra por impulso é a que acontece sem planejamento, geralmente por emoção ou promoção.', 'Você entra na loja para comprar um caderno e sai com um fone em promoção. O caderno era necessidade; o fone foi compra por impulso.', array['Necessidade é essencial; desejo pode esperar.', 'Impulso = sem planejamento, por emoção ou pressa.', 'Esperar 24 horas ajuda a decidir.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('09db1230-2dce-597c-99f9-208d4f696396', 'b741a9eb-c48c-5e77-9f00-b41df5fa1cac', 0, 'classify', 'Classifique cada gasto:', '{"buckets": ["Necessidade", "Desejo"], "items": ["Material escolar", "Passagem para ir à escola", "Jogo novo em lançamento", "Tênis de marca só por moda", "Conta de luz"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('09db1230-2dce-597c-99f9-208d4f696396', '[0, 0, 1, 1, 0]'::jsonb, 'Material escolar: Necessidade; Passagem para ir à escola: Necessidade; Jogo novo em lançamento: Desejo; Tênis de marca só por moda: Desejo; Conta de luz: Necessidade', 'Necessidades são essenciais; desejos podem esperar. A fronteira varia de pessoa para pessoa, o importante é pensar antes de gastar.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('060f378f-4602-56c6-afbe-6b0904c5e2f7', 'b741a9eb-c48c-5e77-9f00-b41df5fa1cac', 1, 'multi', 'Quais sinais indicam uma compra por impulso?', '{"opts": ["Estava na lista de compras planejada", "Comprei por pressa, por causa de uma promoção", "Comprei depois de comparar preços por alguns dias", "Comprei para me sentir melhor na hora, sem pensar"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('060f378f-4602-56c6-afbe-6b0904c5e2f7', '[1, 3]'::jsonb, 'Comprei por pressa, por causa de uma promoção; Comprei para me sentir melhor na hora, sem pensar', 'Pressa, emoção e falta de planejamento são sinais. Esperar 24 horas antes de comprar ajuda a decidir melhor.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_lessons (id, module_id, key, title, position, status) values ('1fa3fab2-9e77-562b-a40a-8676296fe28f', '6cf190d3-e1fd-59b2-bbcf-eaa17326893f', 'ferramentas', 'Organização mensal', 3, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('1fa3fab2-9e77-562b-a40a-8676296fe28f', 'Montar uma rotina simples de revisão mensal.', 'Uma boa rotina tem três passos: registrar, categorizar e revisar. Comparar o que você planejou com o que gastou mostra onde ajustar. O melhor método é o que você consegue manter.', 'No fim do mês, Rita vê que gastou R$ 150 com lazer, mas tinha planejado R$ 100. No mês seguinte, ela reduz as saídas ou aumenta o limite de forma consciente.', array['Registrar, categorizar e revisar.', 'Compare planejado e realizado.', 'O melhor método é o que você mantém.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('75432aa2-175b-58c0-916d-21279e6c180f', '1fa3fab2-9e77-562b-a40a-8676296fe28f', 0, 'quiz', 'Qual é o objetivo da revisão mensal?', '{"opts": ["Se culpar pelos gastos", "Comparar o planejado com o realizado e ajustar", "Apagar os registros", "Gastar o que sobrou"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('75432aa2-175b-58c0-916d-21279e6c180f', '1'::jsonb, 'Comparar o planejado com o realizado e ajustar', 'Revisar serve para aprender e ajustar, sem culpa.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
