insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('eb687473-3525-5bda-bfc2-98f898d6f9b0', 'Transformar um objetivo em valor, prazo e contribuição mensal.', 'Uma meta clara tem objetivo, valor-alvo e prazo. Dividir o que falta pelos meses restantes dá uma referência de quanto guardar por mês. Em geral, curto prazo é até 1 ano, médio prazo de 1 a 5 anos e longo prazo acima disso.', 'Para um notebook de R$ 3.000, já com R$ 900 guardados, faltam R$ 2.100. Em 7 meses, isso dá R$ 300 por mês.', array['Meta = objetivo + valor + prazo.', 'Falta ÷ meses = valor mensal de referência.', 'Prazos: curto, médio e longo.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
