insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('89367997-3379-521c-952e-63468a8f3d59', 'eb687473-3525-5bda-bfc2-98f898d6f9b0', 2, 'classify', 'Classifique o prazo de cada objetivo:', '{"buckets": ["Curto prazo", "Médio prazo", "Longo prazo"], "items": ["Presente de aniversário daqui a 2 meses", "Notebook daqui a 2 anos", "Entrada da faculdade daqui a 8 anos", "Passeio no mês que vem"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('89367997-3379-521c-952e-63468a8f3d59', '[0, 1, 2, 0]'::jsonb, 'Presente de aniversário daqui a 2 meses: Curto prazo; Notebook daqui a 2 anos: Médio prazo; Entrada da faculdade daqui a 8 anos: Longo prazo; Passeio no mês que vem: Curto prazo', 'Uma referência: até 1 ano é curto, de 1 a 5 é médio e acima de 5 é longo.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_lessons (id, module_id, key, title, position, status) values ('813ffd4b-80b1-5b80-9f15-f21c5fae25d1', 'd166c437-23af-5ad9-a4dc-447abfe88791', 'plano', 'Orçamento pessoal', 2, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('813ffd4b-80b1-5b80-9f15-f21c5fae25d1', 'Montar um orçamento fictício usando a regra 50/30/20 como ponto de partida.', 'A regra 50/30/20 sugere dividir a renda em 50% para necessidades, 30% para desejos e 20% para poupança e metas. É um exemplo adaptável: cada realidade pede ajustes. Revise o plano sempre que a renda ou os objetivos mudarem. Aqui você usa só valores fictícios.', 'Com R$ 1.000 fictícios: R$ 500 em necessidades, R$ 300 em desejos e R$ 200 para poupar.', array['50/30/20 é um exemplo, não uma regra fixa.', 'O orçamento precisa fechar 100% da renda.', 'Revise sempre que algo mudar.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('08d6dd3f-932e-503f-85df-e494b748bf45', '813ffd4b-80b1-5b80-9f15-f21c5fae25d1', 0, 'budget', 'Distribua a renda fictícia de R$ 1.000 entre as três categorias. Use pelo menos 10% para poupança e no máximo 60% para necessidades. A soma precisa fechar 100%.', '{"cats": ["Necessidades", "Desejos", "Poupança"], "total": "R$ 1.000,00 (fictício)"}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('08d6dd3f-932e-503f-85df-e494b748bf45', '{"sum": 100, "min": {"2": 10}, "max": {"0": 60}}'::jsonb, 'Uma distribuição possível é 50% / 30% / 20%.', 'Vários planos servem, desde que fechem 100% e respeitem seus limites. A 50/30/20 é só um ponto de partida.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
