insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('6817bcb2-df26-5df2-beb9-3b4933a90c94', 'Entender o que é o Tesouro Direto e o que muda entre os títulos.', 'O Tesouro Direto é um programa em que o governo federal vende títulos públicos a pessoas físicas. Há títulos com prazos e formas de remuneração diferentes, como Selic, prefixado e IPCA+. Consulte preços e regras atuais no site oficial.', 'Ao comprar um título, você empresta dinheiro ao governo e recebe de volta com remuneração no prazo combinado.', array['Títulos públicos são emitidos pelo governo federal.', 'Prazos e remuneração variam por título.', 'Consulte regras atuais no site oficial.']::text[], '[{"n": "Tesouro Direto", "u": "https://www.tesourodireto.com.br"}, {"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
