insert into public.education_lessons (id, module_id, key, title, position, status) values ('0fd3f26c-2c29-58e6-b881-26f3d2672209', '56adfa3a-e813-5202-848b-35872d430c2e', 'selic', 'Selic, juros e inflação', 2, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('0fd3f26c-2c29-58e6-b881-26f3d2672209', 'Relacionar Selic, juros e inflação.', 'A Selic é a taxa básica de juros da economia e é definida periodicamente pelo Copom, do Banco Central. Juros são o preço do dinheiro no tempo, e os juros compostos incidem sobre o valor já acrescido. Inflação é o aumento geral dos preços, que reduz o poder de compra. Consulte a taxa vigente no Banco Central.', 'Se um lanche custava R$ 10 e hoje custa R$ 11, houve inflação: o mesmo dinheiro compra menos.', array['A Selic é a taxa básica e é definida pelo Copom.', 'Juros compostos incidem sobre o valor já acrescido.', 'Inflação reduz o poder de compra.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('0f3cabe3-313d-5bc1-9895-aec0fd7c6f65', '0fd3f26c-2c29-58e6-b881-26f3d2672209', 0, 'quiz', 'Quem define a meta da Selic?', '{"opts": ["O Copom, do Banco Central", "O Tesouro Direto", "A CVM", "Cada banco"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('0f3cabe3-313d-5bc1-9895-aec0fd7c6f65', '0'::jsonb, 'O Copom, do Banco Central', 'O Copom se reúne periodicamente e define a meta da Selic.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
