insert into public.education_lessons (id, module_id, key, title, position, status) values ('6e9b403d-d0c8-5615-8104-7dbae94d0485', '56adfa3a-e813-5202-848b-35872d430c2e', 'fii', 'Fundos imobiliários', 3, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('6e9b403d-d0c8-5615-8104-7dbae94d0485', 'Compreender risco e retorno nos fundos imobiliários.', 'Fundos imobiliários reúnem dinheiro de vários investidores para aplicar em ativos do setor imobiliário. As cotas são negociadas em bolsa e o preço oscila. Rendimentos não são garantidos: dependem do desempenho do fundo.', 'Uma cota comprada a R$ 100 pode valer R$ 92 ou R$ 108 dias depois, e o rendimento mensal também pode variar.', array['Cotas oscilam e rendimentos variam.', 'Retorno maior costuma vir com risco maior.', 'Nada de lucro garantido.']::text[], '[{"n": "Portal do Investidor (CVM)", "u": "https://www.investidor.gov.br"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('f87652e7-2781-576d-8124-eeaf90dac7b8', '6e9b403d-d0c8-5615-8104-7dbae94d0485', 0, 'quiz', 'Sobre fundos imobiliários, é correto dizer:', '{"opts": ["O rendimento é garantido", "As cotas podem oscilar e o rendimento pode variar", "Não têm risco", "Só grandes investidores podem comprar"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('f87652e7-2781-576d-8124-eeaf90dac7b8', '1'::jsonb, 'As cotas podem oscilar e o rendimento pode variar', 'Preço e rendimento variam. Não existe garantia de retorno.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values ('5e73c233-edf3-53eb-8ea1-b35d50806e75', '6e9b403d-d0c8-5615-8104-7dbae94d0485', 1, 'quiz', 'Que relação costuma existir entre risco e retorno?', '{"opts": ["Maior retorno esperado costuma vir com maior risco", "Não há relação", "Menor risco sempre rende mais", "O retorno é sempre garantido"]}'::jsonb) on conflict (lesson_id, position) do update set kind = excluded.kind, prompt = excluded.prompt, public_data = excluded.public_data;
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values ('5e73c233-edf3-53eb-8ea1-b35d50806e75', '0'::jsonb, 'Maior retorno esperado costuma vir com maior risco', 'Quanto maior o retorno que se espera, em geral maior o risco assumido.') on conflict (activity_id) do update set answer = excluded.answer, expected_text = excluded.expected_text, explanation = excluded.explanation;
insert into public.education_lessons (id, module_id, key, title, position, status) values ('4c9aba9b-98b2-5075-8c25-53fcdb7ccc0a', '56adfa3a-e813-5202-848b-35872d430c2e', 'outros', 'Liquidez, risco e diversificação', 4, 'publicado') on conflict (module_id, key) do update set title = excluded.title, position = excluded.position;
insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values ('4c9aba9b-98b2-5075-8c25-53fcdb7ccc0a', 'Comparar liquidez, risco e diversificação em produtos básicos, como o CDB.', 'O CDB é um título emitido por bancos para captar dinheiro. Compare sempre risco, retorno esperado, liquidez, custos e tributação. Diversificar é não concentrar todo o dinheiro em um só investimento. Nenhum investimento deve ser tratado como lucro garantido.', 'Marta deixa a reserva de emergência em algo de fácil resgate e coloca um objetivo distante em um produto de prazo maior.', array['CDB é emitido por bancos.', 'Compare liquidez, risco, custos e tributação.', 'Diversificar reduz a dependência de um só produto.']::text[], '[{"n": "Portal do Investidor (CVM)", "u": "https://www.investidor.gov.br"}, {"n": "Tesouro Direto", "u": "https://www.tesourodireto.com.br"}]'::jsonb, '2026-09-01') on conflict (lesson_id) do update set goal = excluded.goal, explanation = excluded.explanation, example = excluded.example, summary = excluded.summary, sources = excluded.sources, reviewed_on = excluded.reviewed_on;
